// ValoriaGear.cpp: stat bonuses of VALORIA gear on the client.
//
// The game server adds the bonuses in CGame::CalcTotalItemEffect (HG Server\Valoria.cpp); the client
// reads the same table (contents\valoria_gear.txt, generated by tools/valoria_port/build_items.py) so
// the stat window and the HP / MP / SP bars show the same totals as the server.

#include "..\Game.h"
#include <cstdio>
#include <map>
#include <string>

namespace
{
	struct GearRow { int v[CGame::GEAR_COUNT]; };
	std::map<std::string, GearRow> g_gear;
	bool g_bLoaded = false;

	void LoadGear()
	{
		g_bLoaded = true;
		FILE * pFile = fopen("contents\\valoria_gear.txt", "rt");
		if (pFile == NULL) return;
		char cLine[256], cName[64];
		while (fgets(cLine, sizeof(cLine), pFile) != NULL) {
			if (cLine[0] == '/' || cLine[0] == '\r' || cLine[0] == '\n') continue;
			GearRow b = {};
			if (sscanf(cLine, "%63s %d %d %d %d %d %d %d %d %d", cName, &b.v[0], &b.v[1], &b.v[2], &b.v[3],
				&b.v[4], &b.v[5], &b.v[6], &b.v[7], &b.v[8]) == 10)
				g_gear[cName] = b;
		}
		fclose(pFile);
	}
}

int CGame::GearBonus(int iKind) const
{
	if (!g_bLoaded) LoadGear();
	if (iKind < 0 || iKind >= GEAR_COUNT || g_gear.empty()) return 0;
	int iSum = 0;
	for (int i = 0; i < MAXITEMS; i++) {
		if (m_pItemList[i] == NULL || !m_bIsItemEquipped[i]) continue;
		std::map<std::string, GearRow>::const_iterator it = g_gear.find(m_pItemList[i]->m_cName);
		if (it != g_gear.end()) iSum += it->second.v[iKind];
		// VALORIA enchantments and empowering on worn gear (UI\EnchantPanel.cpp); GEAR_* follows Valoria::Mod
		iSum += Valoria::ItemBonus(m_pItemList[i]->m_valoria, iKind, Valoria::ItemTier(m_pItemList[i]->m_sLevelLimit));
	}
	return iSum;
}

// The VALORIA stats of an item kind, in Valoria::Mod order (STR..CRIT); false when it has none.
bool CGame::GearRowOf(const char * pName, int base[Valoria::MOD_CRIT + 1]) const
{
	if (!g_bLoaded) LoadGear();
	for (int k = 0; k <= Valoria::MOD_CRIT; k++) base[k] = 0;
	std::map<std::string, GearRow>::const_iterator it = g_gear.find(pName);
	if (it == g_gear.end()) return false;
	for (int k = 0; k <= Valoria::MOD_CRIT && k < GEAR_COUNT; k++) base[k] = it->second.v[k];
	return true;
}

// m_stat already holds STR / DEX / INT / MAG with the angel bonus but without gear; the server's
// formulas (CClient::GetMaxHP / GetMaxMP / GetMaxSP) include both.
int CGame::MaxHP() const
{
	return (m_stat[STAT_VIT] + GearBonus(GEAR_VIT)) * 3 + m_iLevel * 2 + (m_stat[STAT_STR] + GearBonus(GEAR_STR)) / 2 + GearBonus(GEAR_HP);
}

int CGame::MaxMP() const
{
	return (m_stat[STAT_MAG] + GearBonus(GEAR_MAG)) * 2 + m_iLevel * 2 + (m_stat[STAT_INT] + GearBonus(GEAR_INT)) / 2 + GearBonus(GEAR_MP);
}

int CGame::MaxSP() const
{
	return m_iLevel * 2 + (m_stat[STAT_STR] + GearBonus(GEAR_STR)) * 2;
}

int CGame::GearStatBonus(int iStat) const
{
	switch (iStat) {
	case STAT_STR: return GearBonus(GEAR_STR);
	case STAT_DEX: return GearBonus(GEAR_DEX);
	case STAT_VIT: return GearBonus(GEAR_VIT);
	case STAT_INT: return GearBonus(GEAR_INT);
	case STAT_MAG: return GearBonus(GEAR_MAG);
	}
	return 0;
}
